import sys

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    B = int(next(it))

    edges = []
    for _ in range(B):
        i = int(next(it)) - 1
        j = int(next(it)) - 1
        p = int(next(it))
        edges.append((p, i, j))

    C = int(next(it))
    sets = [None] * N

    for q in range(C):
        x = int(next(it)) - 1
        y = int(next(it)) - 1

        if sets[x] is None:
            sets[x] = {q}
        else:
            sets[x].add(q)

        if sets[y] is None:
            sets[y] = {q}
        else:
            sets[y].add(q)

    edges.sort(reverse=True)

    parent = list(range(N))
    size = [1] * N
    ans = [0] * C

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    for p, u, v in edges:
        ru = find(u)
        rv = find(v)
        if ru == rv:
            continue

        if size[ru] < size[rv]:
            ru, rv = rv, ru

        parent[rv] = ru
        size[ru] += size[rv]

        s_small = sets[rv]
        s_big = sets[ru]

        if s_small is not None:
            if s_big is None:
                sets[ru] = s_small
            else:
                for q in s_small:
                    if q in s_big:
                        ans[q] = p
                        s_big.remove(q)
                    else:
                        s_big.add(q)

        sets[rv] = None

    sys.stdout.write('\n'.join(map(str, ans)) + '\n')


if __name__ == "__main__":
    main()
